using UnityEngine;using System;using System.Collections.Generic;
public static class VerifyTripleScoops{public static object Run(){var settings=Resources.Load<ShovelUpgradeSettings>(ShovelUpgradeSettings.ResourcePath);var result=new List<object>();float previous=0;for(int i=0;i<6;i++){float capacity=settings.shovels[i].capacityKg;float old=capacity/3;float scale=Mathf.Clamp(Mathf.Pow(old/7.5f,1f/3f),1,2.4f);float radius=i<4?.4f*scale:i==4?.55f:.8f;float depth=i<4?.18f*Mathf.Sqrt(scale):i==4?.35f:.5f;radius*=1.44224957f;depth*=1.44224957f;var before=new GrainHeightField(65,8,3);var after=new GrainHeightField(65,8,3);float a=before.Scoop(0,0,radius,depth,old/720f);float b=after.Scoop(0,0,radius*1.44224957f,depth*1.44224957f,capacity/720f);float ratio=b/a;if(Mathf.Abs(ratio-3)>.02f||b<=previous)throw new Exception("Volume/progression failed at "+i+" ratio="+ratio);previous=b;result.Add(new{level=i+1,capacityKg=capacity,visualVolumeRatio=ratio,removedCubicMeters=b});}return result;}}
